class Solution {
public:
    std::vector<int> minReverseOperations(int n, int p, std::vector<int>& banned, int k) {
        std::vector<int> ans(n, -1);
        std::vector<int> parent(n + 2);
        for (int i = 0; i < n + 2; ++i) parent[i] = i;
        auto find = [&](auto& self, int i) -> int {
            return parent[i] == i ? i : (parent[i] = self(self, parent[i]));
        };
        for (int b : banned) parent[b] = find(find, b + 2);
        parent[p] = find(find, p + 2);
        ans[p] = 0;
        std::queue<int> q;
        q.push(p);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            int min_l = std::max(0, u - k + 1);
            int max_l = std::min(n - k, u);
            int left = 2 * min_l + k - 1 - u;
            int right = 2 * max_l + k - 1 - u;
            int curr = find(find, left);
            while (curr <= right) {
                ans[curr] = ans[u] + 1;
                q.push(curr);
                parent[curr] = find(find, curr + 2);
                curr = find(find, curr);
            }
        }
        return ans;
    }
};

class Solution {
    private int[] parent;
    private int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    public int[] minReverseOperations(int n, int p, int[] banned, int k) {
        int[] ans = new int[n];
        java.util.Arrays.fill(ans, -1);
        parent = new int[n + 2];
        for (int i = 0; i < n + 2; i++) parent[i] = i;
        for (int b : banned) parent[b] = find(b + 2);
        parent[p] = find(p + 2);
        ans[p] = 0;
        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        q.offer(p);
        while (!q.isEmpty()) {
            int u = q.poll();
            int minL = Math.max(0, u - k + 1);
            int maxL = Math.min(n - k, u);
            int left = 2 * minL + k - 1 - u;
            int right = 2 * maxL + k - 1 - u;
            int curr = find(left);
            while (curr <= right) {
                ans[curr] = ans[u] + 1;
                q.offer(curr);
                parent[curr] = find(curr + 2);
                curr = find(curr);
            }
        }
        return ans;
    }
}

var minReverseOperations = function(n, p, banned, k) {
    const ans = new Int32Array(n).fill(-1);
    const parent = new Int32Array(n + 2);
    for (let i = 0; i < n + 2; i++) parent[i] = i;
    function find(i) {
        if (parent[i] === i) return i;
        return parent[i] = find(parent[i]);
    }
    for (const b of banned) parent[b] = find(b + 2);
    parent[p] = find(p + 2);
    ans[p] = 0;
    const q = [p];
    let head = 0;
    while (head < q.length) {
        const u = q[head++];
        const minL = Math.max(0, u - k + 1);
        const maxL = Math.min(n - k, u);
        const left = 2 * minL + k - 1 - u;
        const right = 2 * maxL + k - 1 - u;
        let curr = find(left);
        while (curr <= right) {
            ans[curr] = ans[u] + 1;
            q.push(curr);
            parent[curr] = find(curr + 2);
            curr = find(curr);
        }
    }
    return Array.from(ans);
};
